The supplied files contain no existing public API, so I added the standard circular-buffer interface expected for this exercise:

- `write` adds data and throws `buffer_full` when no space remains.
- `force_write` adds data, overwriting the oldest value only when full.
- `read` removes and returns the oldest value, throwing `buffer_empty` when empty.
- `clear` empties the buffer while retaining its capacity.

The implementation uses only the standard library and keeps all template definitions in the header.

circular_buffer.h
```
#if !defined(CIRCULAR_BUFFER_H)
#define CIRCULAR_BUFFER_H

#include <cstddef>
#include <stdexcept>
#include <vector>

namespace circular_buffer {

template <typename T>
class circular_buffer {
public:
    class buffer_full : public std::runtime_error {
    public:
        buffer_full() : std::runtime_error("circular buffer is full") {}
    };

    class buffer_empty : public std::runtime_error {
    public:
        buffer_empty() : std::runtime_error("circular buffer is empty") {}
    };

    explicit circular_buffer(std::size_t capacity)
        : data_(capacity), read_index_(0), write_index_(0), size_(0) {}

    T read() {
        if (size_ == 0) {
            throw buffer_empty();
        }

        T value = data_[read_index_];
        read_index_ = (read_index_ + 1) % data_.size();
        --size_;
        return value;
    }

    void write(const T& value) {
        if (size_ == data_.size()) {
            throw buffer_full();
        }

        data_[write_index_] = value;
        write_index_ = (write_index_ + 1) % data_.size();
        ++size_;
    }

    void force_write(const T& value) {
        if (data_.empty()) {
            return;
        }

        data_[write_index_] = value;
        write_index_ = (write_index_ + 1) % data_.size();

        if (size_ == data_.size()) {
            read_index_ = write_index_;
        } else {
            ++size_;
        }
    }

    void clear() {
        read_index_ = 0;
        write_index_ = 0;
        size_ = 0;
    }

private:
    std::vector<T> data_;
    std::size_t read_index_;
    std::size_t write_index_;
    std::size_t size_;
};

}  // namespace circular_buffer

#endif  // CIRCULAR_BUFFER_H
